mapper.select:
select tpp.test_plugin_package_id as testPluginPackageId, tpp.plugin_id as pluginId, tpp.version as version, tpp.display_name as displayName, tpp.manifest_json as manifestJson, tpp.content_hash as contentHash, tpp.del_status as delStatus, tpp.create_time as createTime, tpp.update_time as updateTime from test_plugin_package tpp where tpp.del_status = 0
and tpp.plugin_id = #{pluginId}
and tpp.version = #{version}
and tpp.display_name like concat('%', #{displayName}, '%')
and tpp.content_hash = #{contentHash}
order by tpp.test_plugin_package_id desc

select count(1)
from test_plugin_package tpp
where tpp.del_status = 0

    and tpp.plugin_id = #{pluginId}


    and tpp.version = #{version}


    and tpp.display_name like concat('%', #{displayName}, '%')


    and tpp.content_hash = #{contentHash}

select tpp.test_plugin_package_id, tpp.plugin_id, tpp.version, tpp.display_name, tpp.manifest_json, tpp.content_hash, tpp.del_status, tpp.create_time, tpp.update_time from test_plugin_package tpp where tpp.del_status = 0
and tpp.plugin_id = #{pluginId}
and tpp.version = #{version}
and tpp.display_name like concat('%', #{displayName}, '%')
and tpp.content_hash = #{contentHash}
order by tpp.test_plugin_package_id desc limit 1
